"""Render rows of strings as a GitHub markdown table."""


def _cell(text):
    return text.strip().replace("|", "\\|")


def _line(cells):
    return "| " + " | ".join(_cell(c) for c in cells) + " |"


def to_markdown(rows):
    """rows is a list of lists of strings; the first row is the header."""
    if not rows:
        raise ValueError("no rows")
    header = rows[0]
    if not header:
        raise ValueError("header has no cells")
    for i, row in enumerate(rows[1:], start=2):
        if len(row) != len(header):
            raise ValueError(f"row {i} has {len(row)} cells, expected {len(header)}")
    separator = "| " + " | ".join("---" for _ in header) + " |"
    lines = [_line(header), separator] + [_line(row) for row in rows[1:]]
    return "\n".join(lines)

